                  {client.name}
                </h3>
                <p className="text-xs text-amber-800 mb-3 leading-relaxed">
                  {client.fullName}
                </p>
                <span className="inline-block px-3 py-1 bg-gradient-to-r from-orange-100 to-amber-100 text-orange-700 text-xs rounded-full font-medium">
                  {client.sector}
                </span>
              </div>
