import { useEffect, useRef } from "react";
import { motion } from "framer-motion";
import 'owl.carousel/dist/assets/owl.carousel.css';
import 'owl.carousel/dist/assets/owl.theme.default.css';

interface SliderImage {
  src: string;
  title: string;
  description: string;
  location: string;
}

interface WorkingOwlSliderProps {
  images: SliderImage[];
  title: string;
  subtitle: string;
}

export function WorkingOwlSlider({ images, title, subtitle }: WorkingOwlSliderProps) {
  const carouselRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const initCarousel = async () => {
      try {
        // Import jQuery and make it globally available
        const { default: $ } = await import('jquery');
        (window as any).$ = $;
        (window as any).jQuery = $;

        // Import Owl Carousel
        await import('owl.carousel');

        if (carouselRef.current) {
          // Small delay to ensure DOM is ready
          setTimeout(() => {
            const $carousel = $(carouselRef.current!);

            // Destroy existing instance if any
            if ($carousel.hasClass('owl-loaded')) {
              $carousel.trigger('destroy.owl.carousel');
              $carousel.removeClass('owl-loaded');
            }

            // Initialize Owl Carousel
            $carousel.owlCarousel({
              items: 1,
              loop: true,
              margin: 0,
              nav: true,
              dots: true,
              autoplay: true,
              autoplayTimeout: 5000,
              autoplayHoverPause: true,
              navText: ['‹', '›'],
              responsive: {
                0: { items: 1 },
                768: { items: 1 },
                1024: { items: 1 }
              }
            });

            console.log('Owl Carousel initialized successfully');
          }, 100);
        }
      } catch (error) {
        console.error('Owl Carousel initialization failed:', error);
      }
    };

    initCarousel();

    // Cleanup function
    return () => {
      if (carouselRef.current && (window as any).$) {
        const $carousel = (window as any).$(carouselRef.current);
        if ($carousel.hasClass('owl-loaded')) {
          $carousel.trigger('destroy.owl.carousel');
        }
      }
    };
  }, []);

  return (
    <section className="bg-gradient-to-br from-slate-50 to-blue-50 dark:from-gray-900 dark:to-blue-900 py-16">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <h2 className="text-4xl font-bold text-gray-900 dark:text-white mb-4">
            {title}
          </h2>
          <p className="text-xl text-gray-600 dark:text-gray-300 max-w-3xl mx-auto">
            {subtitle}
          </p>
        </motion.div>

        <div className="owl-carousel-wrapper">
          <div ref={carouselRef} className="owl-carousel owl-theme">
            {images.map((image, index) => (
              <div key={index} className="item">
                <div className="relative overflow-hidden rounded-2xl shadow-2xl bg-white dark:bg-gray-800">
                  <div className="aspect-[16/9] max-h-[600px]">
                    <img
                      src={image.src}
                      alt={image.title}
                      className="w-full h-full object-cover"
                      loading="lazy"
                    />
                  </div>

                  {/* Project info overlay */}
                  <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent">
                    <div className="absolute bottom-0 left-0 right-0 p-8 text-white">
                      <h3 className="text-2xl md:text-3xl font-bold mb-2">
                        {image.title}
                      </h3>
                      <p className="text-lg mb-2 text-gray-200">
                        {image.description}
                      </p>
                      <p className="text-orange-400 font-semibold">
                        📍 {image.location}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <style>{`
        .owl-carousel-wrapper .owl-nav {
          position: absolute;
          top: 50%;
          width: 100%;
          display: flex;
          justify-content: space-between;
          padding: 0 20px;
          transform: translateY(-50%);
          pointer-events: none;
          z-index: 10;
        }

        .owl-carousel-wrapper .owl-nav button {
          background: rgba(255, 255, 255, 0.9) !important;
          border-radius: 50% !important;
          width: 50px !important;
          height: 50px !important;
          display: flex !important;
          align-items: center !important;
          justify-content: center !important;
          pointer-events: auto;
          border: none !important;
          box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
          transition: all 0.3s ease;
          font-size: 24px !important;
          color: #333 !important;
          font-weight: bold !important;
        }

        .owl-carousel-wrapper .owl-nav button:hover {
          background: #0066CC !important;
          color: white !important;
          transform: scale(1.1);
        }

        .owl-carousel-wrapper .owl-dots {
          text-align: center;
          margin-top: 30px;
